(function (window, document) {
  "use strict";
  function Cleanser() {
    this.forbidden = {
      script: true,
      style: true,
      iframe: true,
      object: true,
      embed: true,
      link: true,
      meta: true
    };
  }
  Cleanser.prototype.cleanAttributes = function (element) {
    var i,
      attr,
      name,
      value;
    if (!element.attributes) {
      return;
    }
    for (i = element.attributes.length - 1; i >= 0; i -= 1) {
      attr = element.attributes[i];
      name = attr.name.toLowerCase();
      value = attr.value || "";
      if (name.indexOf("on") === 0) {
        element.removeAttribute(attr.name);
        continue;
      }
      if ((name === "href" || name === "src" || name === "xlink:href") && /^javascript:/i.test(value)) {
        element.removeAttribute(attr.name);
      }
    }
  };
  Cleanser.prototype.traverse = function (node) {
    var child, next;
    if (!node) {
      return;
    }
    if (node.nodeType === 1) {
      if (this.forbidden[node.nodeName.toLowerCase()]) {
        node.parentNode.removeChild(node);
        return;
      }
      this.cleanAttributes(node);
    }
    child = node.firstChild;
    while (child) {
      next = child.nextSibling;
      this.traverse(child);
      child = next;
    }
  };
  Cleanser.prototype.sanitize = function (html) {
    var container = document.createElement("div");
    container.innerHTML = html || "";
    this.traverse(container);
    return container.innerHTML;
  };
  var cleanser = new Cleanser();
  window.DOMPurify = {
    sanitize: function (html) {
      return cleanser.sanitize(String(html || ""));
    }
  };
}(this, document));
